2 Define Indices And Spatial Graph
We create stable numeric indices for MSOA and year. The MSOA index is based on the complete domain frame so that sampled and unsampled MSOA–years are handled consistently.

area_index &lt;- domain_frame |&gt;
  distinct(domain_id) |&gt;
  arrange(domain_id) |&gt;
  mutate(area_id = row_number())

year_index &lt;- domain_frame |&gt;
  distinct(wave_year) |&gt;
  arrange(wave_year) |&gt;
  mutate(year_id = row_number())

unit_model_data &lt;- unit_sample |&gt;
  left_join(area_index, by = "domain_id") |&gt;
  left_join(year_index, by = "wave_year") |&gt;
  mutate(
    area_iid_id = area_id,
    area_spatial_id = area_id
  ) |&gt;
  arrange(wave_year, area_id)

unit_aggregation_data &lt;- aggregation_frame |&gt;
  left_join(area_index, by = "domain_id") |&gt;
  left_join(year_index, by = "wave_year") |&gt;
  mutate(
    freq_walker = NA_real_,
    area_iid_id = area_id,
    area_spatial_id = area_id
  ) |&gt;
  arrange(wave_year, area_id)


msoa_boundaries_sorted &lt;- msoa_boundaries |&gt;
  inner_join(area_index, by = "domain_id") |&gt;
  arrange(.data$area_id)

msoa_neighbours &lt;- spdep::poly2nb(
  msoa_boundaries_sorted,
  queen = TRUE,
  row.names = msoa_boundaries_sorted$domain_id
)

spatial_graph_file &lt;- tempfile(fileext = ".adj")

spdep::nb2INLA(
  file = spatial_graph_file,
  nb = msoa_neighbours
)
